const $=s=>document.querySelector(s);const sources=[['Pinterest · portrait 1','https://www.pinterest.com/pin/977984875306795007/'],['Pinterest · portrait 4','https://www.pinterest.com/pin/99853316718155050/'],['Pinterest · portrait 5','https://www.pinterest.com/pin/416442296795515555/']];$('#source-links').innerHTML=sources.map(([label,url])=>`<a href="${url}" target="_blank" rel="noreferrer">${label} ↗</a>`).join('');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let clerk=null,ready=false,user=null,admin=false,filter='upcoming',attendance=[],activities=[];
const date=new Date();date.setDate(date.getDate()+5);date.setHours(18,0,0,0);const sample=(id,title,description,location,days)=>({id,title,description,location,starts_at:new Date(+date+days*86400000).toISOString(),ends_at:new Date(+date+days*86400000+7200000).toISOString()});
const examples=[sample('demo-1','An evening with the brotherhood','An evening to reconnect, share a meal, and spend time with the circle.','Location to be announced',0),sample('demo-2','Purpose in action','Come together for a shared community initiative. Details will follow.','Location to be announced',7),sample('demo-3','The monthly circle','Conversations, new ideas, and the next chapter for Eros.','Location to be announced',14)];
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',5000)}
function notice(title,text){$('#notice-title').textContent=title;$('#notice-text').textContent=text;$('#auth-widget').replaceChildren();if(!$('#notice').open)$('#notice').showModal()}
$('.close').onclick=()=>$('#notice').close();$('#notice').addEventListener('click',e=>{if(e.target===$('#notice'))$('#notice').close()});
async function api(action,body){const token=clerk?.session?await clerk.session.getToken():null;const r=await fetch('/api/portal?action='+action,{method:body?'POST':'GET',headers:{...(body?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{})},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed. Please try again.');return d}
async function login(signup=false){if(!ready){notice('Member access is loading.','Please try again in a moment. If sign-in remains unavailable, reload the page.');return}if(user){$('#member').scrollIntoView();return}try{if(signup)clerk.openSignUp({forceRedirectUrl:location.origin+'/#member'});else clerk.openSignIn({forceRedirectUrl:location.origin+'/#member'});}catch{toast('Unable to open authentication. Please reload and try again.')}}
document.querySelectorAll('[data-login]').forEach(b=>b.onclick=()=>login());document.querySelectorAll('[data-signup]').forEach(b=>b.onclick=()=>login(true));
function renderMember(){const signedIn=Boolean(user);document.querySelectorAll('[data-login]').forEach(b=>b.textContent=signedIn?'My circle ↗':(b.closest('header')?'Sign in ↗':'Member sign in ↗'));document.querySelectorAll('[data-signup]').forEach(b=>{b.hidden=signedIn});$('#member-name').textContent=signedIn?(user.fullName||user.firstName||'Eros member'):'The circle awaits.';$('#member-status').textContent=signedIn?attendance.length+' gatherings attended':'Sign in or create an account to join your circle.';$('#member-actions').replaceChildren();if(signedIn){const out=document.createElement('button');out.className='text-button';out.textContent='Sign out ↗';out.onclick=async()=>{out.disabled=true;api('session',{event:'sign_out'}).catch(()=>{});try{await clerk.signOut();user=null;admin=false;attendance=[];renderMember();render()}catch{out.disabled=false;toast('Sign-out failed. Please try again.')}};$('#member-actions').append(out)}else{const inside=document.createElement('button');inside.className='text-button';inside.textContent='Create account ↗';inside.onclick=()=>login(true);$('#member-actions').append(inside)}$('#admin').hidden=!admin;}
function render(){const list=activities.filter(a=>filter==='all'||filter==='attended'?filter!=='attended'||attendance.some(r=>r.activity_id===a.id):new Date(a.ends_at)>=new Date());$('#activity-list').innerHTML=list.map(a=>{const d=new Date(a.starts_at),checked=attendance.some(r=>r.activity_id===a.id);return `<article class="event"><div class="event-date">${d.toLocaleDateString('en',{month:'short'}).toUpperCase()}<strong>${d.getDate()}</strong></div><div><span class="eyebrow">${a.id.startsWith('demo-')?'EXAMPLE GATHERING':'BROTHERHOOD GATHERING'}</span><h3>${esc(a.title)}</h3><p>${esc(a.description)}</p><p class="meta">${esc(d.toLocaleString('en-PH',{weekday:'short',hour:'numeric',minute:'2-digit',month:'short',day:'numeric'}))} · ${esc(a.location)}</p></div><button data-check="${esc(a.id)}" ${checked?'disabled':''}>${checked?'✓ Attendance recorded':'Check in ↗'}</button></article>`}).join('')||'<p class="muted" style="padding:35px 0">'+(filter==='attended'?(user?'No attendance recorded yet.':'Sign in to see your attendance.'):'No activities announced yet. Check back soon.')+'</p>';document.querySelectorAll('[data-check]').forEach(b=>b.onclick=async()=>{if(!user)return login(false);if(b.dataset.check.startsWith('demo-'))return toast('This is an illustrative gathering. An admin must publish a real activity first.');b.disabled=true;try{await api('checkin',{activityId:b.dataset.check});await refresh();toast('Your attendance has been recorded.')}catch(e){toast(e.message);b.disabled=false}})}
async function refresh(){renderMember();const results=await Promise.allSettled([api('activities'),...(user?[api('me')]:[])]);if(results[0].status==='fulfilled'){activities=results[0].value.activities;$('#activity-state').textContent='THE EROS SCHEDULE'}else{activities=[];$('#activity-state').textContent='SCHEDULE UNAVAILABLE'}if(user&&results[1]?.status==='fulfilled'){attendance=results[1].value.attendance;admin=results[1].value.admin;if(!results[1].value.databaseReady)$('#member-status').textContent='Signed in · attendance is awaiting activation.'}else if(user){admin=false;attendance=[];toast('You are signed in. Member records are temporarily unavailable.')}renderMember();if(user&&results[1]?.status==='fulfilled'&&!results[1].value.databaseReady)$('#member-status').textContent='Signed in · attendance is awaiting activation.';render();if(admin)try{await loadAdmin()}catch(e){$('#audit').textContent=e.message}}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));render()});$('#admin-link').onclick=()=>{if(!user)return login(false);if(!admin)return notice('Administrator access required.','Your signed-in account has no administrator role. Contact the Eros administrator.');$('#admin').scrollIntoView()};
async function loadAdmin(){const d=await api('admin');$('#metrics').innerHTML=[['Activities',d.activities],['Check-ins',d.attendance.length],['Members',d.members]].map(([l,n])=>`<div class="metric"><strong>${n}</strong><span class="muted">${l}</span></div>`).join('');$('#audit').innerHTML=d.logs.map(r=>`<div class="audit-row">${esc(r.name)} · ${esc(r.event)}<small>${esc(r.details)} · ${esc(new Date(r.created_at).toLocaleString())}</small></div>`).join('')||'<p class="muted">No member activity yet.</p>';window.exportRecords=d.attendance}
$('#create-activity').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),b=Object.fromEntries(f);b.starts=new Date(b.starts).toISOString();b.ends=new Date(b.ends).toISOString();if(b.ends<=b.starts)return toast('End time must be after the start time.');const button=e.target.querySelector('button');button.disabled=true;try{await api('create',b);e.target.reset();await refresh();toast('Activity published.')}catch(e){toast(e.message)}finally{button.disabled=false}};
$('#export').onclick=()=>{const rows=[['Member','Activity','Checked in'],...(window.exportRecords||[]).map(r=>[r.name,r.title,r.checked_at])];const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='eros-attendance.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
async function boot(){let config;try{config=await api('config')}catch{try{const r=await fetch('/clerk-config.json');config=await r.json()}catch{}}if(!config?.publishableKey){activities=examples;render();return}try{const host=atob(config.publishableKey.split('_').slice(2).join('_')).replace(/\$$/,'');const script=document.createElement('script');script.src='https://'+host+'/npm/@clerk/clerk-js@5/dist/clerk.browser.js';script.dataset.clerkPublishableKey=config.publishableKey;script.crossOrigin='anonymous';await new Promise((resolve,reject)=>{script.onload=resolve;script.onerror=()=>reject(Error('Authentication could not load'));document.head.append(script)});clerk=window.Clerk;await clerk.load({appearance:{variables:{colorPrimary:'#bc3933',colorBackground:'#141111',colorText:'#f3f1ee',colorInputBackground:'#211a18',colorInputText:'#f3f1ee',borderRadius:'12px'}}});ready=true;user=clerk.user;renderMember();clerk.addListener(async state=>{if((state.user?.id||null)!==(user?.id||null)){user=state.user;admin=false;attendance=[];renderMember();await refresh();if(user)api('session',{event:'sign_in'}).catch(()=>{})}});if(user)api('session',{event:'sign_in'}).catch(()=>{});await refresh()}catch{activities=examples;render();toast('Unable to load sign-in. Check your connection and reload.')}}
boot();
